SELECT SUM(value) AS week_active_users, MIN(metric_time__day) AS week_start, MAX(metric_time__day) AS week_end
FROM (
  SELECT metric_time__day, value FROM "query_result_r2"
) t;

WITH last_week AS (
  SELECT value FROM (VALUES
    (DATE '2026-07-06',84),(DATE '2026-07-07',113),(DATE '2026-07-08',80),(DATE '2026-07-09',95),(DATE '2026-07-10',84),(DATE '2026-07-11',88),(DATE '2026-07-12',87)
  ) AS t(day, value)
), prev_week AS (
  SELECT value FROM (VALUES
    (DATE '2026-06-29',108),(DATE '2026-06-30',100),(DATE '2026-07-01',97),(DATE '2026-07-02',98),(DATE '2026-07-03',104),(DATE '2026-07-04',113),(DATE '2026-07-05',103)
  ) AS t(day, value)
)
SELECT (SELECT SUM(value) FROM last_week) AS last_week_total, (SELECT SUM(value) FROM prev_week) AS prev_week_total, (SELECT SUM(value) FROM last_week)-(SELECT SUM(value) FROM prev_week) AS difference;

