SELECT COUNT(*) FILTER (WHERE dark_mode = True) AS dark_on, COUNT(*) AS total
FROM (
  SELECT customer_id, MAX(CASE WHEN preference_key = 'dark_mode' THEN preference_value END) IN ('true','True','1') AS dark_mode
  FROM (
    SELECT customer_id, preference_key, preference_value
    FROM dim_customer_preferences
  )
  GROUP BY customer_id
) t;

SELECT SUM(value_minutes) AS total_minutes FROM (
 SELECT SUM(duration_seconds)/60.0 AS value_minutes
 FROM fct_app_opens ao
 JOIN dim_customer c ON ao.customer_id = c.customer_id
 WHERE ao.opened_date BETWEEN '2026-07-06' AND '2026-07-12' AND c.is_internal = FALSE
) t;

SELECT SUM(value) AS q1_2026_marketing_spend
FROM (
  SELECT value FROM fct_spend_row WHERE spend_row__spend_date >= '2026-01-01' AND spend_row__spend_date < '2026-04-01' AND spend_row__channel IN ('content_seo','paid_search','partnerships','referral')
) t;
